class Solution {
public:
    int prefixCount(vector<string>& words, string pref) {
        int count = 0;
        int m = static_cast<int>(pref.size());
        for (const string& w : words) {
            if (static_cast<int>(w.size()) >= m && w.compare(0, m, pref) == 0) {
                ++count;
            }
        }
        return count;
    }
};
